<script setup lang="ts">import{toast}from'vue-sonner';import{z}from'zod';const auth=useAuthStore();const{audit}=useDatabase();const form=reactive({current:'',password:'',confirmation:''});const show=ref(false);async function save(){const passwordSchema=z.string().min(1,'Password baru wajib diisi').min(8,'Password minimal 8 karakter').regex(/[A-Z]/,'Password harus memiliki minimal 1 huruf besar').regex(/[0-9]/,'Password harus memiliki minimal 1 angka').regex(/[^A-Za-z0-9]/,'Password harus memiliki minimal 1 karakter khusus');const result=z.object({current:z.string().min(1,'Password saat ini wajib diisi'),password:passwordSchema,confirmation:z.string().min(1,'Konfirmasi password wajib diisi')}).refine(value=>value.password===value.confirmation,{message:'Konfirmasi password tidak sama',path:['confirmation']}).safeParse(form);if(!result.success){notifyValidationErrors(result.error);return}try{await useApi().request('/me/password',{method:'PUT',body:{current:result.data.current,password:result.data.password}});if(auth.user)auth.user.mustChangePassword=false;await audit('PASSWORD','Profile','Password diperbarui');Object.assign(form,{current:'',password:'',confirmation:''});toast.success('Password berhasil diubah');navigateTo('/')}catch(error){toast.error(error instanceof Error?error.message:'Password gagal diubah')}}</script>
<template><div class="mx-auto max-w-xl"><div class="mb-6"><h2 class="text-2xl font-bold">Ubah Password</h2><p class="text-sm text-slate-500">Gunakan password yang kuat dan mudah Anda ingat.</p></div><form class="card space-y-5 p-6 sm:p-8" @submit.prevent="save"><div><label class="label">Password Saat Ini</label><input v-model="form.current" name="current-password" autocomplete="current-password" class="input" :type="show?'text':'password'"></div><div><label class="label">Password Baru</label><input v-model="form.password" name="new-password" autocomplete="new-password" class="input" :type="show?'text':'password'"></div><div><label class="label">Konfirmasi Password Baru</label><input v-model="form.confirmation" name="new-password-confirmation" autocomplete="new-password" class="input" :type="show?'text':'password'"></div><label class="flex items-center gap-2 text-sm text-slate-500"><input v-model="show" type="checkbox" class="accent-teal-600"> Tampilkan password</label><div class="flex justify-end"><button class="btn-primary">Update</button></div></form></div></template>
